SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "崔胤与昭宗谋去宦官，南北司相倾。", "citation": "卷262·光化三年（900）·zztj-v262-y0900-p009·原文件第14行", "note": "原文：崔胤日与上谋去宦官，宦官知之。由是南、北司益相憎嫉，各结籓镇为援以相倾夺。；核对说明：“上”为昭宗；结藩镇为互相援引的史书概述，不推出各方具体结盟清单。", "status": "draft", "id": "211f9d68-2d22-54e6-8f84-056f4cebde54", "subject_id": "280d56a8-1c41-51c8-8a4c-c0b8f45ef642", "source_id": "68eb7d17-c638-5231-b199-971efe49f7db"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "900年王抟罢相前；确日未载", "citation": "卷262·光化三年（900）·zztj-v262-y0900-p009·原文件第14行", "note": "原文：崔胤日与上谋去宦官，宦官知之。由是南、北司益相憎嫉，各结籓镇为援以相倾夺。；核对说明：“上”为昭宗；结藩镇为互相援引的史书概述，不推出各方具体结盟清单。", "status": "draft", "id": "d33598ba-b504-525c-bcf0-0c9cea99dad6", "subject_id": "280d56a8-1c41-51c8-8a4c-c0b8f45ef642", "source_id": "68eb7d17-c638-5231-b199-971efe49f7db"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记崔胤：谋去宦官者。", "citation": "卷262·光化三年（900）·zztj-v262-y0900-p009·原文件第14行", "note": "原文：司空、门下侍郎、同平章事王抟，明达有度量，时称良相。上素疾宦官枢密使硃道弼、景务修专横，崔胤日与上谋去宦官，宦官知之。由是南、北司益相憎嫉，各结籓镇为援以相倾夺。抟恐其致乱，从容言于上曰：“人君当务明大体，无所偏私。宦官擅权之弊，谁不知之！顾其势未可猝除，宜俟多难渐平，以道消息。愿陛下言勿轻泄以速奸变。”胤闻之，谮抟于上曰：“王抟奸邪，已为道弼辈外应。”上疑之。及胤罢相，意抟排己，愈恨之。及出镇广州，遗硃全忠书，具道抟语，令全忠表论之。全忠上言：“胤不可离辅弼之地，抟与敕使相表里，同危社稷。”表连上不已。上虽察其情，迫于全忠，不得已，胤至湖南复召还。丁卯，以胤为司空、门下侍郎、同平章事，抟罢为工部侍郎。以道弼监荆南军，务修监青州军。戊辰，贬抟溪州刺史；己巳，又贬崖州司户。道弼长流欢州，务修长流爱州。是日，皆赐自尽。抟死于蓝田驿，道弼、务修死于霸桥驿。于是胤专制朝政，势震中外，宦官皆侧目，不胜其愤。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "c79043b7-2ee6-5f64-8d91-3f3f5678646d", "subject_id": "b071b1d3-7e73-526b-8e08-d1abf5ed205f", "source_id": "68eb7d17-c638-5231-b199-971efe49f7db"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "崔胤：谋去宦官者。", "citation": "卷262·光化三年（900）·zztj-v262-y0900-p009·原文件第14行", "note": "原文：崔胤日与上谋去宦官，宦官知之。由是南、北司益相憎嫉，各结籓镇为援以相倾夺。；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "c1d9